// ABOUTME: Pins catalogue CRSs without a datum shift whose scale factor is written +k_0= against PROJ.
// ABOUTME: Reads tests/fixtures/restatement-reference.txt, generated by tools/gen_restatement_reference.py.
//! Reference parity for source CRSs that need no datum shift but whose
//! catalogue definition proj4rs 0.1.10 misreads.
//!
//! The catalogue writes the scale factor of these projections as `+k_0=`,
//! which proj4rs ignores. The reprojector must agree with the PROJ inverse
//! projection on every row.

use std::path::Path;

use tileforge_crs::{CrsError, Reprojector, SourceCrs};

/// Largest accepted distance between the reprojector and PROJ, in metres.
/// The two compute the same projection, so the difference is numerical only.
const PARITY_TOLERANCE_M: f64 = 1.0e-5;

/// Fixture CRSs that proj4rs 0.1.10 cannot build. `Reprojector::new` refuses
/// them with `UnknownEpsg` before and after the restatement.
const UNBUILDABLE: [u16; 9] = [2085, 2086, 5458, 6200, 6201, 6202, 6966, 32061, 32062];

/// EPSG:8325, NAD83(2011) / Oregon Mitchell zone (m), `+k_0=0.99927`, at
/// the centre of its area of use, and the EPSG:4978 position of the PROJ
/// inverse projection placed on the WGS 84 ellipsoid.
const OREGON_MITCHELL: [f64; 3] = [34_765.939_480_213_44, 21_143.121_376_820_14, 123.456];
const OREGON_MITCHELL_ECEF: [f64; 3] = [
    -2_288_336.385_015_172_4,
    -3_933_334.476_891_188,
    4_454_311.162_280_009,
];

struct Row {
    epsg: u16,
    src: [f64; 3],
    expected_ecef: [f64; 3],
}

fn reference_rows() -> Vec<Row> {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/restatement-reference.txt");
    let body =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    body.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .map(|line| {
            let cols: Vec<&str> = line.split_whitespace().collect();
            assert_eq!(cols.len(), 7, "expected 7 fields in {line:?}");
            let number = |i: usize| {
                cols[i]
                    .parse::<f64>()
                    .unwrap_or_else(|e| panic!("{:?} is not f64: {e}", cols[i]))
            };
            Row {
                epsg: cols[0].parse().expect("EPSG code"),
                src: [number(1), number(2), number(3)],
                expected_ecef: [number(4), number(5), number(6)],
            }
        })
        .collect()
}

fn distance(a: [f64; 3], b: [f64; 3]) -> f64 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

#[test]
fn oregon_mitchell_zone_uses_its_scale_factor() {
    let rp = Reprojector::new(SourceCrs::new(8325)).unwrap();
    assert_eq!(rp.datum_shift(), None);
    let delta = distance(rp.to_ecef(OREGON_MITCHELL).unwrap(), OREGON_MITCHELL_ECEF);
    assert!(
        delta < PARITY_TOLERANCE_M,
        "{delta} m from the PROJ reference"
    );
}

#[test]
fn every_restated_crs_matches_the_proj_reference() {
    let rows = reference_rows();
    assert!(
        rows.len() > 300,
        "fixture is incomplete: {} rows",
        rows.len()
    );
    let mut failures = Vec::new();
    let mut unbuildable = std::collections::BTreeSet::new();
    let mut worst = 0.0_f64;
    for row in &rows {
        let rp = match Reprojector::new(SourceCrs::new(row.epsg)) {
            Ok(rp) => rp,
            Err(CrsError::UnknownEpsg(_)) => {
                unbuildable.insert(row.epsg);
                continue;
            }
            Err(e) => {
                failures.push(format!("EPSG:{}: {e}", row.epsg));
                continue;
            }
        };
        assert_eq!(
            rp.datum_shift(),
            None,
            "EPSG:{} has a datum shift",
            row.epsg
        );
        match rp.to_ecef(row.src) {
            Ok(ecef) => {
                let delta = distance(ecef, row.expected_ecef);
                worst = worst.max(delta);
                if delta.is_nan() || delta > PARITY_TOLERANCE_M {
                    failures.push(format!(
                        "EPSG:{} {:?}: {delta:.6} m from PROJ",
                        row.epsg, row.src
                    ));
                }
            }
            Err(e) => failures.push(format!("EPSG:{} {:?}: {e}", row.epsg, row.src)),
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} reference rows differ from PROJ by more than {PARITY_TOLERANCE_M} m \
         (worst {worst:.6} m); first rows:\n{}",
        failures.len(),
        rows.len(),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    let expected: std::collections::BTreeSet<u16> = UNBUILDABLE.into_iter().collect();
    assert_eq!(unbuildable, expected, "CRSs that fail to build");
}
